window.GRAMMAR_TOPICS=[{"id":"sentence_parts","en":"Sentence Parts","zh":"句子成分","ruleEn":"The subject tells who or what. The predicate tells what the subject does or is.","ruleZh":"主语说明谁或什么；谓语说明主语做什么或处于什么状态。","example":"The curious student solved the puzzle quickly.","focus":"Subject = The curious student; Verb = solved; Object = the puzzle; Adverbial = quickly."},{"id":"sentence_patterns","en":"Sentence Patterns","zh":"基本句型","ruleEn":"Common patterns include S+V, S+V+C, S+V+O, S+V+IO+DO, and S+V+O+C.","ruleZh":"常见句型包括主谓、主系表、主谓宾、主谓双宾和主谓宾宾补。","example":"The soup tastes delicious.","focus":"S + linking verb + complement."},{"id":"clauses","en":"Phrases & Clauses","zh":"短语与从句","ruleEn":"An independent clause can stand alone; a dependent clause cannot.","ruleZh":"独立从句可单独成句；从属从句不能单独成句。","example":"We stayed inside because it was raining.","focus":"Independent: We stayed inside. Dependent: because it was raining."},{"id":"tenses","en":"Verb Tenses","zh":"动词时态","ruleEn":"Choose tense by time and action state: simple, progressive, perfect.","ruleZh":"选择时态时同时看时间和动作状态：一般、进行、完成。","example":"She has finished her homework already.","focus":"Present perfect = has + past participle."},{"id":"agreement","en":"Subject-Verb Agreement","zh":"主谓一致","ruleEn":"The verb agrees with the true subject, not a nearby noun.","ruleZh":"谓语动词与真正主语一致，不要被临近名词干扰。","example":"The basket of apples is heavy.","focus":"basket is singular → is."},{"id":"pronouns","en":"Pronouns","zh":"代词","ruleEn":"Pronoun case depends on its job; references must be clear.","ruleZh":"代词使用主格或宾格取决于句中作用，并且指代必须清楚。","example":"Please give the book to Maya and me.","focus":"After a preposition, use object pronoun."},{"id":"modifiers","en":"Modifiers","zh":"修饰语","ruleEn":"Adjectives modify nouns; adverbs modify verbs; opening modifiers must logically describe the next noun.","ruleZh":"形容词修饰名词；副词修饰动词；开头修饰语必须合理修饰后面的名词。","example":"Walking home, Maya saw a rainbow.","focus":"Maya is the one walking home."},{"id":"connectors","en":"Prepositions & Conjunctions","zh":"介词与连词","ruleEn":"Prepositions show relationships; conjunctions connect ideas and show logic.","ruleZh":"介词表示关系；连词连接内容并表达逻辑。","example":"I was tired, but I finished my homework.","focus":"but = contrast."},{"id":"voice","en":"Active & Passive Voice","zh":"主动与被动","ruleEn":"Passive voice uses be + past participle and emphasizes the receiver.","ruleZh":"被动语态使用 be + 过去分词，强调动作承受者。","example":"The project was completed by the class.","focus":"was completed = passive."},{"id":"punctuation","en":"Punctuation","zh":"标点","ruleEn":"Use commas, semicolons, colons, quotation marks, and apostrophes based on structure.","ruleZh":"根据句子结构正确使用逗号、分号、冒号、引号和撇号。","example":"Bring three things: pencils, paper, and glue.","focus":"A colon introduces a list after a complete clause."},{"id":"errors","en":"Sentence Errors","zh":"句子常见错误","ruleEn":"Fragments are incomplete; run-ons and comma splices join clauses incorrectly.","ruleZh":"残句不完整；连写句和逗号拼接错误连接独立句。","example":"I studied; I passed.","focus":"Semicolon correctly joins related independent clauses."},{"id":"parallel","en":"Parallel Structure","zh":"平行结构","ruleEn":"Items in a list or comparison should use the same grammatical form.","ruleZh":"并列项目或比较项应保持相同语法形式。","example":"She likes reading, swimming, and hiking.","focus":"All three use -ing."}];
